      "sequence_id": "string",
      "offset": "number",
      "expected_checkpoint": "string",
      "reason": "string"
    }
  }
}
```

`kv_crc`: CRC32 checksum computed over the KV cache snapshot state range and context sequence.

JSON schema:
```json
{
  "type": "object",
  "properties": {
    "error": { "type": "string" },
    "code": { "type": "string" },
    "message": { "type": "string" },
    "resume_details": {
      "type": "object",
      "properties": {
        "stream_id": { "type": "string" },
        "sequence_id": { "type": "integer" },
        "last_flushed_offset": { "type": "integer" },
        "reason": { "type": "string" },
        "recoverability": { "type": "string" }
      },
      "required": ["stream_id", "sequence_id", "last_flushed_offset", "reason"]
    }
  },
  "required": ["error", "code", "message", "resume_details"]
}
```

`kv_crc` computation:
32-bit FNV hash (or CRC) computed over `stream_id`, `flush_offset`/`sequence_id`, and key-value state payload.
